// Package api is the Go client for the Ionhour Integration API v1
// (https://api.ionhour.com/api/v1): projects, HTTP checks, heartbeat jobs,
// regions and the other v1 resources.
//
// It is a separate module from the zero-dependency heartbeat SDK
// (github.com/ionhour/go-sdk), so the generated client's runtime dependency
// never reaches heartbeat users.
//
// The low-level client (client.gen.go, types.gen.go) is generated by
// oapi-codegen from the committed OpenAPI document; regenerate it with
// `yarn openapi:go-client`. The hand-written facade adds:
//
//   - [NewClient] with env fallbacks (IONHOUR_API_KEY, IONHOUR_API_BASE_URL)
//   - bearer auth and a User-Agent on every request
//   - the SDK contract retry policy (never 4xx; 429 honours Retry-After;
//     5xx/network backoff 1s, 2s, 2s; 3 attempts)
//   - [*APIError] parsed from the v1 error envelope, with [IsUnauthorized],
//     [IsForbidden], [IsNotFound], [IsConflict] and [IsRateLimited]
//   - [ListAll] pagination, wrapped by [Client.ListAllChecks] and friends
//   - automatic idempotency keys on checks_create, jobs_create and
//     projects_create, overridable with [WithIdempotencyKey]
//
// Always construct the client with [NewClient]; the zero value is not usable.
//
// Quick start:
//
//	c, err := api.NewClient(api.WithAPIKey(os.Getenv("IONHOUR_API_KEY")))
//	if err != nil { ... }
//	me, err := c.Whoami(ctx)
//
//	rsp, err := c.ProjectsListWithResponse(ctx, &api.ProjectsListParams{})
//	if err != nil { ... }
//	if err := c.CheckResponse(rsp.HTTPResponse, rsp.Body); err != nil { ... }
//	for _, p := range rsp.JSON200.Items { ... }
//
// The API key never appears in fmt output of a Client or in error text.
package api
